    # transform the grid
    for r in range(rows):
        if grid[r][spine] != 1:
            continue               # spine not present in this row

        # determine whether there is a gap right after the spine
        gap = (spine + 1 < cols and grid[r][spine + 1] == 0)

        # if there is a gap and the column left of the spine contains a 1,
        # we use that neighbour column as the reference; otherwise we keep the spine.
        if gap and spine > 0 and grid[r][spine - 1] == 1:
            ref_col = spine - 1
        else:
            ref_col = spine

        # count 1's to the left and to the right of the reference column
        left_cnt = sum(1 for c in range(ref_col) if grid[r][c] == 1)
        right_cnt = sum(1 for c in range(ref_col + 1, cols) if grid[r][c] == 1)

        fill = right_cnt - left_cnt
        if fill < 0:
            fill = 0
        # we can only fill columns 1 .. ref_col‑1
        max_fill = ref_col - 1
        if fill > max_fill:
            fill = max_fill

        # place 2's starting at column 1
        for c in range(1, fill + 1):
            grid[r][c] = 2

    return grid

